INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.105.1',
  '2026-09-30',
  'Пульт ТВ: папку с коллекцией фильмов можно отправить как фильмы, а не как сериал',
  E'Скрипт отправки считал сериалом любую папку: коллекция из восьми фильмов про Гарри Поттера приехала бы на приставку одним «сериалом» с восемью «сериями». Теперь у него есть ключ «--films»: каждый файл уезжает отдельным фильмом, а название собирается из имени файла — номер в коллекции отбрасывается, год переезжает в скобки, хвост раздачи срезается. «1 Гарри Поттер и филосовский камень 2001г.mkv» становится «Гарри Поттер и филосовский камень (2001)».',
  E'send-series.py: ключ --films. Папка при нём не создаётся на той стороне, dest_base = FILMS_ROOT, имя каждого файла даёт film_name(): срезается ведущий номер («1 », «02. »), год (в том числе «2001г») переносится в скобки, точки заменяются пробелами у имён без пробелов, отбрасываются «[…]» и хвост релиза по FILM_TAGS (x264, BDRip, WEB-DL, 1080p, remux, rus/eng…). План печатает получившиеся названия — их видно в --dry-run до отправки.\n\nПроверено на коллекции Гарри Поттера (8 файлов, 124 ГБ, h264 1080p): с ключом — восемь плиток с правильными именами и годами, без ключа — прежнее поведение (один «сериал»). У этих раздач по 3–12 звуковых дорожек, все ac3; дорожка 0 везде «Дубляж», поэтому --audio 0; на выходе ~101 ГБ вместо 124 за счёт отброшенных дорожек и субтитров.'
);
